// The theme of the report.
//
// It is a Typst file that exports a `theme` function. The renderer wraps the
// document in it, so everything set here applies to the whole document.

#let theme(body) = {
  set page(
    paper: "a4",
    margin: (x: 22mm, y: 25mm),
    header: context {
      if counter(page).get().first() > 1 {
        align(center, text(size: 8pt, fill: rgb("#6b7280"))[
          #counter(heading).display()
        ])
      }
    },
    footer: context {
      align(center, text(size: 8pt, fill: rgb("#6b7280"))[
        #counter(page).display() of #counter(page).final().first()
      ])
    },
  )

  set text(font: "Inter", size: 10.5pt, fill: rgb("#111827"))
  set par(justify: true, leading: 0.65em)

  show heading.where(level: 1): it => {
    set text(weight: "bold", size: 24pt)
    block(above: 0pt, below: 6pt, it)
  }
  show heading.where(level: 2): it => {
    set text(weight: "bold", size: 15pt)
    block(above: 8mm, below: 3mm, it)
  }
  show heading.where(level: 3): it => {
    set text(weight: "bold", size: 12pt)
    block(above: 6mm, below: 2mm, it)
  }

  show list: it => block(above: 0pt, below: 3mm, it)
  show enum: it => block(above: 0pt, below: 3mm, it)

  show quote: it => block(
    above: 3mm,
    below: 3mm,
    inset: (left: 4mm),
    stroke: (left: 1.2pt + rgb("#d1d5db")),
    text(fill: rgb("#4b5563"), it),
  )

  body
}

// The theme of the resume.
//
// It is a Typst file that exports a `theme` function. The renderer wraps the
// document in it, so everything set here applies to the whole document.

#let theme(body) = {
  set page(paper: "a4", margin: 16mm)

  set text(font: "Inter", size: 10pt, fill: rgb("#111827"))
  set par(leading: 0.55em)

  show heading.where(level: 1): it => {
    set text(weight: "bold", size: 20pt)
    block(above: 0pt, below: 5mm, it)
  }
  show heading.where(level: 2): it => {
    set text(weight: "bold", size: 10pt, fill: rgb("#6b7280"))
    block(
      above: 5mm,
      below: 2mm,
      stroke: (bottom: 0.5pt + rgb("#d1d5db")),
      it,
    )
  }

  show list: it => block(above: 0pt, below: 2mm, it)

  body
}

// The theme of the article.
//
// It is a Typst file that exports a `theme` function. The renderer wraps the
// document in it, so everything set here applies to the whole document.

#let theme(body) = {
  set page(
    paper: "a4",
    margin: 24mm,
    footer: context {
      align(center, text(font: "Inter", size: 8pt, fill: rgb("#6b7280"))[
        #counter(page).display()
      ])
    },
  )

  set text(font: "Source Serif 4", size: 11.5pt, fill: rgb("#1f2937"))
  set par(justify: true, leading: 0.7em)

  show heading.where(level: 1): it => {
    set text(font: "Inter", weight: "bold", size: 22pt)
    block(above: 0pt, below: 5mm, it)
  }
  show heading.where(level: 2): it => {
    set text(font: "Inter", weight: "bold", size: 14pt)
    block(above: 8mm, below: 3mm, it)
  }
  show heading.where(level: 3): it => {
    set text(font: "Inter", weight: "bold", size: 12pt)
    block(above: 6mm, below: 2mm, it)
  }

  show quote: it => block(
    above: 5mm,
    below: 5mm,
    inset: (left: 5mm),
    stroke: (left: 1.2pt + rgb("#cbd5e1")),
    text(style: "italic", fill: rgb("#475569"), it),
  )

  show raw: it => text(font: "Inter", it)

  body
}
